const pair = (big, small, hiBig) => `${hiBig ? ring(34, 40, 28) : ring(78, 61, 19)}${chr(big, 4, 12, 60)}${chr(small, 58, 42, 40)}${hiBig ? arrowDown(34, 12) : arrowDown(78, 42)}`;
