const sign = (inner) => `${shadow(16, 50, 93)}<rect x="47" y="60" width="6" height="33" fill="${P.grayD}"/><g class="a-bob"><circle cx="50" cy="38" r="30" fill="#fff"/><circle cx="50" cy="38" r="26" fill="${P.blue}"/>${inner}</g>`;

